package pe.ganadoconecta;
import static org.assertj.core.api.Assertions.assertThat;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.csrf;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import java.time.Instant;import java.util.*;import com.fasterxml.jackson.databind.ObjectMapper;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfSystemProperty;import org.springframework.beans.factory.annotation.*;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.web.servlet.*;import org.springframework.transaction.annotation.Transactional;import pe.ganadoconecta.modulos.identidad.aplicacion.TokensAcceso;
@SpringBootTest(properties={"debug=false","logging.level.root=WARN","ganadoconecta.seguridad.origen-permitido=https://127.0.0.1:5173"}) @AutoConfigureMockMvc @ActiveProfiles("postgres") @EnabledIfSystemProperty(named="ganadoconecta.postgres.integration-test",matches="true") @Transactional
class ReproduccionPostgresIntegrationTest extends SoporteJwtPostgres{
 @Autowired MockMvc mvc;@Autowired JdbcTemplate jdbc;@Autowired ObjectMapper json;@Autowired TokensAcceso tokens;UUID usuario,sesion,ganaderia,hembra,macho;String jwt;
 @BeforeEach void preparar(){usuario=UUID.randomUUID();sesion=UUID.randomUUID();ganaderia=UUID.randomUUID();hembra=UUID.randomUUID();macho=UUID.randomUUID();jdbc.update("INSERT INTO identidad.usuario(id,email_normalizado,password_hash,estado) VALUES(?,?,'$argon2id$fixture','ACTIVO')",usuario,usuario+"@reproduccion.invalid");jdbc.update("INSERT INTO identidad.sesion_dispositivo(id,usuario_id,creado_en,vence_en) VALUES(?,?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP+interval '1 hour')",sesion,usuario);jdbc.update("INSERT INTO identidad.ganaderia(id,nombre,propietario_usuario_id,estado) VALUES(?,'Aislada',?,'ACTIVA')",ganaderia,usuario);jdbc.update("INSERT INTO identidad.membresia(id,ganaderia_id,usuario_id,rol,estado) VALUES(?,?,?,'PROPIETARIO','ACTIVA')",UUID.randomUUID(),ganaderia,usuario);jdbc.update("INSERT INTO ganado.animal(id,ganaderia_id,sexo,nombre,creado_por,creado_en) VALUES(?,?, 'HEMBRA','Hembra sintética',?,CURRENT_TIMESTAMP),(?,?,'MACHO','Macho sintético',?,CURRENT_TIMESTAMP)",hembra,ganaderia,usuario,macho,ganaderia,usuario);jwt=tokens.emitir(usuario,sesion,Instant.now(),Instant.now().plusSeconds(600)).valor();}
 String ruta(){return "/api/v1/ganaderias/"+ganaderia+"/animales/"+hembra+"/eventos-reproductivos";}
 String cuerpo(UUID op,UUID ev,String tipo,String estado)throws Exception{Map<String,Object>b=new LinkedHashMap<>();b.put("operationId",op);b.put("eventId",ev);b.put("schemaVersion",1);b.put("tipo",tipo);b.put("fecha","2026-11-01");if(estado!=null)b.put("estadoGestacion",estado);b.put("reproductorAnimalId",macho);b.put("responsable","Responsable sintético");return json.writeValueAsString(b);}
 ResultActions guardar(String b)throws Exception{return mvc.perform(post(ruta()).header("Authorization","Bearer "+jwt).header("Origin","https://127.0.0.1:5173").with(csrf().asHeader()).contentType("application/json").content(b));}
 @Test void registraListaYReprocesaSinDuplicar()throws Exception{UUID op=UUID.randomUUID(),ev=UUID.randomUUID();String b=cuerpo(op,ev,"MONTA",null);guardar(b).andExpect(status().isCreated());guardar(b).andExpect(status().isOk()).andExpect(jsonPath("$.resultado").value("REPROCESADO"));mvc.perform(get(ruta()).header("Authorization","Bearer "+jwt)).andExpect(status().isOk()).andExpect(jsonPath("$[0].tipo").value("MONTA"));assertThat(jdbc.queryForObject("SELECT count(*) FROM reproduccion.evento_reproductivo WHERE animal_id=?",Integer.class,hembra)).isEqualTo(1);}
 @Test void evaluacionConservaFechaInformadaYNoInterpretaObservaciones()throws Exception{Map<String,Object>b=new LinkedHashMap<>();b.put("operationId",UUID.randomUUID());b.put("eventId",UUID.randomUUID());b.put("schemaVersion",1);b.put("tipo","EVALUACION_GESTACION");b.put("fecha","2026-11-01");b.put("estadoGestacion","CONFIRMADA");b.put("fechaProbableParto","2027-01-10");guardar(json.writeValueAsString(b)).andExpect(status().isCreated());mvc.perform(get(ruta()).header("Authorization","Bearer "+jwt)).andExpect(jsonPath("$[0].fechaProbableParto").value("2027-01-10"));}
 @Test void validaHembraEstadoCsrfYPermiso()throws Exception{UUID original=hembra;hembra=macho;guardar(cuerpo(UUID.randomUUID(),UUID.randomUUID(),"MONTA",null)).andExpect(status().isUnprocessableEntity());hembra=original;guardar(cuerpo(UUID.randomUUID(),UUID.randomUUID(),"EVALUACION_GESTACION",null)).andExpect(status().isUnprocessableEntity());String b=cuerpo(UUID.randomUUID(),UUID.randomUUID(),"MONTA",null);mvc.perform(post(ruta()).header("Authorization","Bearer "+jwt).header("Origin","https://127.0.0.1:5173").contentType("application/json").content(b)).andExpect(status().isForbidden());jdbc.update("UPDATE identidad.membresia SET rol='LECTOR' WHERE usuario_id=?",usuario);guardar(b).andExpect(status().isForbidden());mvc.perform(get(ruta()).header("Authorization","Bearer "+jwt)).andExpect(status().isOk());}
 @Test void aíslaGanaderiaYRechazaMembresiaRevocada()throws Exception{UUID real=hembra;hembra=UUID.randomUUID();mvc.perform(get(ruta()).header("Authorization","Bearer "+jwt)).andExpect(status().isNotFound());hembra=real;jdbc.update("UPDATE identidad.membresia SET estado='REVOCADA',revocado_en=CURRENT_TIMESTAMP WHERE usuario_id=?",usuario);guardar(cuerpo(UUID.randomUUID(),UUID.randomUUID(),"MONTA",null)).andExpect(status().isForbidden());mvc.perform(get(ruta()).header("Authorization","Bearer "+jwt)).andExpect(status().isForbidden());}
}
